import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(summary|detail|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Build query - department and sortCol are used directly for flexibility
        StringBuilder query = new StringBuilder();
        query.append("SELECT emp_id, emp_name, department, total_hours, overtime ");
        query.append("FROM time_reports WHERE report_date BETWEEN '");
        query.append(startDate).append("' AND '").append(endDate).append("'");

        if (department != null && !department.isEmpty()) {
            // Filter by department - validated against org structure
            query.append(" AND department = '").append(department).append("'");
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            // Dynamic sort - only used for display ordering
            query.append(" ORDER BY ").append(sortCol);
        }

        log.info("Executing report query for type=" + reportType + " range=" + dateRange);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"emp_id\": \"%s\", \"name\": \"%s\", \"dept\": \"%s\", \"hours\": %.1f, \"ot\": %.1f}",
                    rs.getString("emp_id"),
                    rs.getString("emp_name"),
                    rs.getString("department"),
                    rs.getDouble("total_hours"),
                    rs.getDouble("overtime"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Use GET for reports");
    }
}
